-- lyric previews from LRCLIB (scripts/fetch-previews.mjs). Safe to re-run; never overwrites an existing preview.
alter table public.songs add column if not exists preview text check (char_length(preview) <= 200);

update public.songs set preview = v.preview from (values
('anh biet em di chang tro ve|vu khanh', 'Anh biết em đi chẳng trở về Dặm ngàn liễu khuất với sương che Em đừng quay lại nhìn anh nữa Anh biết em đi chẳng trở về Không phải vì anh chẳng tại em Hoa thu tàn tạ rụng bên thềm '),
('cho em muon kiep|vu khanh', 'Chiều buông vấn vương cung đàn Lá rơi úa vàng, nụ hoa não nùng vội tàn Còn đây lá thư phai màu, gió mây gợi sầu Buồn dâng đôi mắt sâu Lặng vương trên đường một mình Chiều mưa âm th'),
('nguoi di qua doi toi|tran thai hoa', 'Người đi qua đời tôi Trong những chiều đông sầu Mưa mù lên mấy vai Gió mù lên mấy trời Người đi qua đời tôi Hồn lưng miền rét mướt Vàng xưa đầy dấu chân Đen tối vùng lãng quên Bàn '),
('co lang gieng|vu khanh', 'Hôm nay trời xuân bao tươi thắm Dừng gót phiêu linh về thăm nhà Chân bước trên đường đầy hoa đào rơi Tôi đã hình dung nét ai đang cười Tôi mơ trời xuân bao tươi thắm Đôi mắt trong '),
('tinh phu|vu khanh', 'Chuyện tình mười mấy năm qua Nay bỗng xót xa những khi sầu dâng Còn đâu ngày quen biết nhau Đã yêu em rồi yêu cả cuộc đời Khi em đã phụ lòng anh Nỡ phụ lòng anh đau thương em để lạ'),
('tinh nghia doi ta chi the thoi|vu khanh', 'Thôi là hết anh đi đường anh Tình duyên mình chỉ bấy nhiêu thôi Còn mong gì hình bóng xa xôi Nhắc làm gì chuyện năm xưa Cho tim thêm ngẩn ngơ Thôi là hết em đi đường em Từ nay sầu '),
('xin tra no nguoi|vu khanh', 'Anh bảo anh viết thật dài cho anh Nhưng những dòng chữ không thể dài bằng nỗi nhớ được Nỗi nhớ đã đi qua hết quãng đời dài hơn 20 năm Đi từ Huế lên Đà Lạt Về Sài Gòn Và âm ỉ như mộ'),
('mua nang la|vu khanh', 'Em hai mươi tuổi em là nắng Em hai mươi tuổi em là mưa Sài Gòn nắng mưa em ngày ấy Còn là hạt bụi giữa hư vô Em hai mươi tuổi, em bây giờ Chân qua phố phường phố ngẩn ngơ Sài Gòn h'),
('thang sau troi mua|vu khanh', 'Tháng sáu trời mưa trời mưa không dứt Trời không mưa anh cũng lạy trời mưa Anh lạy trời mưa phong kín đường về Và đêm ơi xin cứ dài vô tận Mình dựa vào nhau cho thuyền ghé bến Sưởi'),
('bai khong ten so 3|vu khanh', 'Yêu nhau cho nhau nụ cười Thương nhau cho nhau cuộc đời Mà đời đâu biết đợi Để tình nhân kết đôi Yêu nhau cho nhau một lần Thương nhau thương cho một lần Một lần thôi vĩnh biệt Một'),
('cuoc song em on khong|thai chau', 'Ngày hôm nay, mình xa nhau được mấy ngày Tại sao anh lại thế này, lệ anh sao cứ tuôn chảy Em, vẫn yêu ai đúng không vậy? Đừng nói anh đã chia tay, sẽ chẳng phải với anh đấy Anh phả'),
('ao lua ha dong|vu khanh', 'Nắng Sài Gòn anh đi mà chợt mát Bởi vì em mặc áo lụa Hà Đông Anh vẫn yêu màu áo ấy vô cùng Anh vẫn yêu màu áo ấy vô cùng Anh vẫn nhớ em ngồi đây tóc ngắn Mà mùa thu dài lắm ở chung'),
('hai vi sao lac|thai chau', 'Người về một chiều thu gió heo may Về đâu có nhớ chăng những vì sao long lanh Đưa tiễn người một đêm không trăng Nói sao nên lời, lòng buồn như chiều rơi Như trong đêm khuya những '),
('yeu em vao coi chet|vu khanh', 'Anh đã biết anh đã biết yêu em là tuyệt vọng Mà vì sao mà vì sao anh vẫn cứ yêu em Con giun con nằm uốn khúc giữa đêm trường Rồi giun chết chết tương tư vì sao sáng Anh vẫn biết an'),
('ngu di em|thai chau', 'Ngủ đi em, ngủ đi em, ngủ đi em Hỏa pháo bừng lên trong đêm Là lúc mình yêu nhau thêm Đừng khóc sầu chi nghe em Thôi ngủ nhé, thôi ngủ đi Hãy quên bao nỗi niềm, ngủ đi Ngủ đi em, n'),
('boi vi la khi yeu|thai chau', 'Nói cho anh đi Liệu yêu một người bằng hết con tim là đúng hay đang sai? Mà sao em ơi anh cứ buồn hoài như thế Nước mắt rơi nhiều như thế y-yeh uh oh Nói cho anh đi Em có yêu anh n'),
('linh hon tuong da & lan dau cung la lan cuoi|thai chau', 'Trên dốc đá, tôi tình cờ quen nàng Ngồi bên nhau, gọi tên nhau để rồi xa nhau Em đã đến và đã đến như áng mây Như cánh chim trôi trên bầu trời Ôi hình hài một vài giờ vui Tôi muốn '),
('mua thu khong tro lai|duy quang', 'Em ra đi mùa thu Mùa thu không trở lại Em ra đi mùa thu Sương mờ giăng âm u Em ra đi mùa thu Mùa thu không còn nữa Đếm lá úa mùa thu Đo sầu ngập tim tôi Ngày em đi Nghe chơi vơi nã'),
('vo ngua tren doi co non|thai chau', 'Em dấu yêu ơi, anh đang quay về mười năm xa vắng Anh đã đưa em, đưa em đi tìm một giấc mơ đời Mười năm lạc loài phải không em? Mười năm hận thù trĩu trong tim Ta trót vong thân, ta'),
('chuyen tinh buon|duy quang', 'Năm năm rồi không gặp Từ khi em lấy chồng Anh dặm trường mê mải Đời chia như nhánh sông Phong thư tình ngây dại Và vai môi rất mềm Những hẹn hò cuống quýt Trên lối xưa thiên đàng N'),
('ban tinh ca dau tien|thai chau', 'Ngày không em, không lung linh nắng trên con đường Dòng người lướt qua, riêng anh ngẩn ngơ miên man Và em hỡi có biết tim anh vấn vương bóng hình đợi mong Nhưng anh nín lặng, không'),
('muoi nam tinh cu|duy quang', 'Mười năm không gặp tưởng tình đã cũ Mây bay bao năm tưởng mình đã quên Như mưa bay đi một trời thương nhớ Anh ơi, bên kia có còn mắt buồn? Mười năm cách biệt một lần bỡ ngỡ Quên đi'),
('linh hon tuong da / lan dau cung la lan cuoi|thai chau', 'Trên dốc đá, tôi tình cờ quen nàng Ngồi bên nhau, gọi tên nhau để rồi xa nhau Em đã đến và đã đến như áng mây Như cánh chim trôi trên bầu trời Ôi hình hài một vài giờ vui Tôi muốn '),
('vet thuong cuoi cung|ho hoang yen', 'Người vừa tặng ta vết thương đau ngọt ngào Chẳng nợ nần gì nhau hãy để tình ta bay cao Từ vào cuộc vui đã chớm nghe lừa dối Che giấu trên nụ môi những lời yêu quá tả tơi Thà một lầ'),
('nguoi tinh dep xinh xinh|gia huy', 'Này người tình người đẹp xinh xinh Đừng xa tôi dù là giây phút Trói hồn tôi trong vòng tay quên đi ngày mai Và từng ngày là nghìn mê say Càng mong quên lại càng mong đến Nhớ nụ hôn'),
('doi tinh doi ao|gia huy', 'Kiếm một người thật lòng sao khó quá Đến bây giờ anh mới nhận ra Anh biết rằng em thương thầm anh ta Rồi em giấu anh thời gian qua Ở bên người em thấy vui không Chắc hơn anh vì em '),
('nguoi la thoang qua|gia huy', 'Phải chăng lúc này em có một người thế thay Họ cho em nhiều bên em sớm tối nuông chiều Còn anh chỉ là giống như người lạ thoáng qua Đau đến tận cùng nhưng vẫn giả vờ hạnh phúc Phải'),
('ai noi yeu em dem nay|ho hoang yen', 'Ai nói yêu em đêm nay? Ai nói yêu em đêm mai? Ai sẽ nói yêu em sau này? Son phấn nào giết ngây thơ? Ánh đèn nào màu đơn côi? Lệ sao nhiều hơn mưa lũ Ai dìu bước em đêm nay? Ai dìu '),
('chien si vo danh|ho hoang yen', '作曲 : phạm duy Mờ trong bóng chiều Một đoàn quân thấp thoáng Núi cây rừng Lắng tiếng nghe hình dáng Của người anh hùng Lạnh lùng theo trống dồn Trên khu đồi nương Im trong chiều buô'),
('giang hai khong do nang|gia huy', 'Phật từng nghe qua bài ca dao mà sao vẫn không độ nàng Một tiếng mõ không che đi vạn ý phàm Là bỉ ngạn hoa phủ tương tư đường xưa loang lổ vết máu Mộng này chết đoạn một khúc tơ sầ'),
('no me ca thanh xuan|gia huy', 'Mẹ đã đổi cả thanh xuân mẹ vì con quên cả chính mình Nhọc nhằn chín tháng mười hôm thêm nhiều năm lặng thầm hy sinh Rồi ngày con lớn lên hơn ngu dại nên chẳng nghĩ biết nhiều Tạo đ'),
('vong tay nguoi ay|philip huy', 'Tình như giấc mơ Hãy giữ ai ơi cho giấc mơ còn đầy Một khi đã yêu đừng quên Con tim sẽ mang thêm bao ưu phiền Em hỡi chớ có thờ ơ Yêu em với nụ cười đắm say Bầu trời đẹp xinh Yêu e'),
('tuyet trang|philip huy', 'Anh biết chiều nay em anh buồn lắm Đã hẹn nhưng chẳng thấy bóng anh sang Khi nắng công trường soi bước em Khi chiều kéo lại bao nhiêu nhớ mong Khi đường bay chờ anh tung cánh sắt Đ'),
('doa hoa hong|gia huy', 'Đang cập nhật'),
('em co hieu long anh|gia huy', 'Đã rất lâu rồi khi từ đâu, ngàn sau, cuộc tình chia hai lối ngưới hỡi nếu уêu đùng gian dối có những đêm buồn ngồi một mình lặng thinh đọi chờ em lên tiếng chỉ thấу trái tim maù bă'),
('mong nguoi ta luon tot luon yeu em|luu chi vy', 'Một cuộc tình buồn không có ai mong đợi đâu Một mình ngồi buồn không có ai muốn vậy đâu Vẫn nhớ ngày xưa chuyện tình ta như trăng sao Vẫn mong lúc em sẽ quay về Tại vì một người đã'),
('dieu buon dem trang|hong phuong', 'Đêm dưới trăng mơ màng đàn buông sáu câu não lòng Than trách than duyên mình giờ đây lẻ bóng người ơi Tình sao sớm vội tan khi người đi chẳng hẹn quay về Ai nỡ quên câu thề cho cun'),
('giac mo ngay hom ay|luu chi vy', 'Đã bao lần một mình anh trên phố Bàn chân bước ngập ngừng vấn vương Về lại nơi xưa để thấy em yêu Còn đó với bao ngày sau Giấc mơ nào một mình anh ôm lấy Để rồi biết bầu trời vẫn t'),
('chang kho|luu chi vy', 'Na-na-na-na-na-na-na Na-na-na-na-na-na-na Na-na-na-na, na-na-na-na-na-na-na Na-na-na-na-na-na-na Na-na-na-na-na-na-na Na-na-na-na, na-na-na-na, na-na-na Người ta thường nói tôi khờ'),
('nguoi ay va toi em chon ai|luu chi vy', 'Hẹn chiều nay mà sao không thấy em Gió hiu hiu, lòng bỗng nghe lạnh thêm Chiều mù sương hay mù khói thuốc anh Em không lại anh nhủ lòng sao đây? Em cứ hẹn chiều mai rồi lại không t'),
('khong bao gio quen anh|thien quang', 'Tôi viết lên đây với tất cả chân thành của lòng tôi trao anh Ngày nao đã quen nhau vì chung hướng đời mình trót trao nhau nụ cười Và tình yêu đó tôi đem ép trong tim Dù bụi thời gi'),
('khong the o ben nhau|luu chi vy', 'Buồn làm gì khi con tim ai cũng phải đổi thay một ngày Nuối tiếc làm chi khi đôi ta đã cách xa từ đây đến suốt đời Một người giữ lấy ngàn nỗi đau Một người giữ lấy ngàn nhớ thương '),
('bac trang tinh doi|luu chi vy', 'Thà là bỏ đi hết ta làm lại từ đầu đầu Thà là bỏ đi hết ta chẳng nợ gì nhau nhau Cho quên đi đớn đau khỏi bận tâm ngày sau sau Vì một người như thế có đáng hay không Ngày mai tôi s'),
('phuong buon|jang mi', 'Anh đến với em vào một ngày trời đẹp nắng Một ngày phượng hồng thắm cho đôi mắt buồn xa xăm Phượng hay bâng khuâng tưởng chừng như cô đơn Nên khi chiều xuống thấy vấn vương trong t'),
('duong tim bang lang|thien quang', 'Hàng cây xanh thắm màu Trên con đường ngày xưa Hai ta chung lối mộng Em thương sắc tím bằng lăng Anh thương màu áo trắng Tan trường hoa áo tung tăng Tình bao năm thắm nồng Nhưng ch'),
('chuyen tinh khong di vang|quynh trang', 'Vàng cây lá bay Đôi tay ngây buồn mang suy tư về Này đôi mắt nhung Kiêu sa môi mềm tìm đến cơn mê Niềm tin đã lạnh theo tháng năm giá băng Anh có nghe ngoài phố đang kết hoa? Bao n'),
('em di xem hoi trang ram|jang mi', 'Nhân gian xem hội trăng tròn Trăng tròn 16 thật to Người ta đi đứng thật đông Đêm nay là hội trăng tròn Em đi xem hội trăng tròn Áo quần, hài gấm bảnh bao Nhìn lên trên trời ông tr'),
('cho nguoi|jang mi', 'Một người con gái Đứng nghiêng nghiêng vành nón lá Đường chiều bờ đê Lối xưa kỷ niệm thiết tha Lòng nàng sao lưu luyến quá Hẹn hò một người đi xa Mà năm tháng đã dần qua Chuyện tìn'),
('chuyen hoa sim|jang mi', 'Rừng hoang đẹp nhất hoa màu tím Chuyện tình thương nhất chuyện hoa sim Có người con gái xuân vời vợi Tóc còn ngăn ngắn chưa đầy búi Ngày xưa nàng vẫn yêu màu tím Chiều chiều lên nh'),
('loi chua noi|jang mi', 'Những câu ân tình chưa nói Giờ bỗng tan như làn mây khói Khi tình yêu đã chết thật rồi Giờ làm gì cũng thế thôi Còn thiếu nhau bao lời xin lỗi Định nói ra nhưng rồi lại thôi Phút g'),
('danh phan|jang mi', 'Thương ai sang sông, lòng chẳng còn vấn vương Bao nhiêu tơ vương gửi vào làn khói sương Có thương em không người ơi? Có đau khi ta lìa đôi? Sao nỡ lấy tâm ý ấy gửi tặng người đến s'),
('duyen phan|jang mi', 'Phận là con gái chưa một lần yêu ai Nhìn về tương lai mà thấy như sông rộng đường dài Cảnh nhà neo đơn bầy em chưa lớn Trĩu đôi vai gánh nhọc nhằn Thầy mẹ thương em nhờ tìm người s'),
('yeu la phai lieu|jang mi', 'Ngày gặp anh người mang cho em cảm giác bình yên Làm con tim em phút giây xao động Rồi lòng cứ nhớ mong Từng ngày trôi mà sao tim em vẫn mãi bồi hồi Nhìn anh bâng khuâng chẳng dám '),
('nguoi tinh mua dong / ti tach|jang mi', 'Sao em vẫn còn trông chờ mong ngóng Bóng dáng ai trở về Ngoài ban công mưa đã rơi rơi rồi Mà sao em vẫn còn chơi vơi ngồi, babe Tim em đau người đâu nào hay biết Nhớ thương phải ch'),
('ngua o thuong nho|khuu huy vu', 'Tôi xin người cứ gian dối Cho tôi tưởng người cũng yêu tôi May ra còn được thấy đời vui Khi cơn mưa mùa đông đang tới Xin giã từ ngày tháng rong chơi Đôi tay này vẫn chờ mong Con t'),
('moi duyen que|khuu huy vu', 'Trời đã se sợi chỉ hồng Để chúng ta nên vợ chồng Đồng ruộng xanh mênh mông trời đông Nhà chúng ta ven hai bờ sông Có nhịp cầu đưa lối Mình đã yêu nhau từ thuở nào Lời mến thương dâ'),
('ve dau mai toc nguoi thuong|khuu huy vu', 'Hồn lỡ sa vào đôi mắt em Chiều nao xõa tóc ngồi bên rèm Thầm ước nhưng nào đâu dám nói Khép tâm tư lại thôi Đường hoa vẫn chưa mở lối Đời lắm phong trần tay trắng tay Trời đông ngạ'),
('nho thuong lam chi|jang mi', 'Người ra đi, người ra đi Ngồi nơi đây nhớ thương làm gì Anh sẽ không quan tâm gì nữa đâu Người ra đi, người ra đi Ngồi nơi đây nhớ thương làm gì Anh chẳng quay lại nữa đâu nhớ thươ'),
('xin dung goi cho em|saka truong tuyen', 'Anh và em cùng nhau dạo trên đường khu phố Đông người qua, từ đâu, từ xa một cô bướm xa Kề bên, cạnh bên và giờ cô đã nói rằng "Anh giờ đã là một người yêu nàng, không còn yêu tôi '),
('chung mot dong song|khuu huy vu', '"Chung một dòng sông Anh và em đã thương nhau thật lòng Nhiều đêm nằm mơ Thấy mình đẹp mối duyên thơ Thuyền hoa đã neo bến mong chờ Đôi ta sánh vai bước chung đường Họ hàng mừng vu'),
('dau cang dau|saka truong tuyen', 'Cố kiềm lòng đừng xót xa cho người vui ấm áp bên người ta. Dẫu đoạn đường còn xót xa thôi từ đây cố quên bao ngày qua. Dấu giọt lệ vào khoé mi tim quặn đau trước lúc ta biệt ly. Hỏ'),
